def stable_order(xs):
    result = []
    for value in xs:
        pos = len(result)
        while pos > 0 and result[pos - 1] > value:
            pos -= 1
        result.insert(pos, value)
    return result

def fold_one(xs):
    value = xs[0]
    for item in xs[1:]:
        if item < value:
            value = item
    return value

def fold_two(xs):
    value = xs[0]
    for item in xs[1:]:
        if item > value:
            value = item
    return value

def program(xs, pre, use_left, use_right):
    if pre:
        xs = stable_order(xs)

    xs = sorted(xs)  # TARGET_A

    first = fold_one(xs) if use_left else xs[0]
    last = fold_two(xs) if use_right else xs[-1]
    return first, last
